ALTER TABLE `organizations` ADD COLUMN `isBlocked` BOOLEAN NOT NULL DEFAULT false, ADD COLUMN `blockedReason` VARCHAR(191) NULL;
CREATE TABLE `subscription_plans` (`id` VARCHAR(191) NOT NULL,`name` VARCHAR(191) NOT NULL,`description` TEXT NULL,`monthlyPrice` DECIMAL(12,2) NOT NULL,`includedLocations` INTEGER NOT NULL DEFAULT 1,`includedEmployees` INTEGER NOT NULL DEFAULT 1,`extraLocationPrice` DECIMAL(12,2) NOT NULL DEFAULT 0,`extraEmployeePackSize` INTEGER NOT NULL DEFAULT 1,`extraEmployeePackPrice` DECIMAL(12,2) NOT NULL DEFAULT 0,`features` JSON NOT NULL,`isActive` BOOLEAN NOT NULL DEFAULT true,`sortOrder` INTEGER NOT NULL DEFAULT 0,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `subscription_plans_name_key`(`name`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `organization_subscriptions` (`id` VARCHAR(191) NOT NULL,`organizationId` VARCHAR(191) NOT NULL,`planId` VARCHAR(191) NOT NULL,`status` VARCHAR(191) NOT NULL DEFAULT 'active',`periodStartsAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`periodEndsAt` DATETIME(3) NOT NULL,`graceEndsAt` DATETIME(3) NULL,`extraLocations` INTEGER NOT NULL DEFAULT 0,`extraEmployeePacks` INTEGER NOT NULL DEFAULT 0,`autoBlockOnPastDue` BOOLEAN NOT NULL DEFAULT true,`reminderDaysBefore` INTEGER NOT NULL DEFAULT 5,`lastReminderAt` DATETIME(3) NULL,`notes` TEXT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `organization_subscriptions_organizationId_key`(`organizationId`), INDEX `organization_subscriptions_status_periodEndsAt_idx`(`status`,`periodEndsAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `subscription_payments` (`id` VARCHAR(191) NOT NULL,`organizationId` VARCHAR(191) NOT NULL,`subscriptionId` VARCHAR(191) NULL,`planId` VARCHAR(191) NULL,`amount` DECIMAL(12,2) NOT NULL,`currency` VARCHAR(191) NOT NULL DEFAULT 'MXN',`status` VARCHAR(191) NOT NULL DEFAULT 'paid',`paidAt` DATETIME(3) NULL,`periodStartsAt` DATETIME(3) NULL,`periodEndsAt` DATETIME(3) NULL,`reference` VARCHAR(191) NULL,`notes` TEXT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `subscription_payments_organizationId_createdAt_idx`(`organizationId`,`createdAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `organization_subscriptions` ADD CONSTRAINT `organization_subscriptions_organizationId_fkey` FOREIGN KEY (`organizationId`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `organization_subscriptions_planId_fkey` FOREIGN KEY (`planId`) REFERENCES `subscription_plans`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `subscription_payments` ADD CONSTRAINT `subscription_payments_organizationId_fkey` FOREIGN KEY (`organizationId`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `subscription_payments_subscriptionId_fkey` FOREIGN KEY (`subscriptionId`) REFERENCES `organization_subscriptions`(`id`) ON DELETE SET NULL ON UPDATE CASCADE, ADD CONSTRAINT `subscription_payments_planId_fkey` FOREIGN KEY (`planId`) REFERENCES `subscription_plans`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
